.docker-sub {
    border-bottom: 1px solid #ccc;
    height: 30px;
    line-height: 30px;
    margin-bottom: 15px;
}

.docker-sub .on {
    border-bottom: 2px solid #20a53a;
    color: #20a53a;
    font-weight: bold;
    font-family: "Songti";
}
.docker-sub span {
    display: inline-block;
    font-size: 14px;
    height: 30px;
    padding: 0 25px;
    cursor: pointer;
}

.docker-environments {
    resize: none;
    width: 330px;
    height: 80px;
    line-height: 20px;
    padding: 5px 8px;
    border: 1px solid #ddd;
    font-size: 12px;
}
